insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000995511','40000000-0000-4000-8000-000000099551','Nomeie primeiro a ideia central: Como $p=2>1$, trata-se de uma integral de potência convergente.',1),('60000000-0000-4000-8000-000000995512','40000000-0000-4000-8000-000000099551','Escreva a definição ou a relação escolhida antes de substituir os dados.',2),('60000000-0000-4000-8000-000000995513','40000000-0000-4000-8000-000000099551','Ao final, teste se o resultado preserva as condições do enunciado e descarte erros de sinal, domínio ou hipótese.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099551','Converge e vale $\frac{1}{1}$.','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. Como $p=2>1$, trata-se de uma integral de potência convergente. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000995511','40000000-0000-4000-8000-000000099551','Leia o objetivo','Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.',1),('70000000-0000-4000-8000-000000995512','40000000-0000-4000-8000-000000099551','Reconheça a ideia','Como $p=2>1$, trata-se de uma integral de potência convergente.',2),('70000000-0000-4000-8000-000000995513','40000000-0000-4000-8000-000000099551','Escreva a relação','Registre a definição, fórmula ou teste que se aplica antes de simplificar.',3),('70000000-0000-4000-8000-000000995514','40000000-0000-4000-8000-000000099551','Desenvolva a análise','Execute a transformação necessária e obtenha: Converge e vale $\frac{1}{1}$.',4),('70000000-0000-4000-8000-000000995515','40000000-0000-4000-8000-000000099551','Confira a conclusão','Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.',5) on conflict (id) do update set question_id=excluded.question_id,title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
