insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000995571','40000000-0000-4000-8000-000000099557','Nomeie primeiro a ideia central: A descontinuidade está em $x=0$; como o expoente $2/3$ é menor que $1$, o limite existe.',1),('60000000-0000-4000-8000-000000995572','40000000-0000-4000-8000-000000099557','Escreva a definição ou a relação escolhida antes de substituir os dados.',2),('60000000-0000-4000-8000-000000995573','40000000-0000-4000-8000-000000099557','Ao final, teste se o resultado preserva as condições do enunciado e descarte erros de sinal, domínio ou hipótese.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099557','Converge e vale $3$.','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. A descontinuidade está em $x=0$; como o expoente $2/3$ é menor que $1$, o limite existe. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
