insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099564','Converge e vale $5$.','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. A descontinuidade está em $x=0$; como o expoente $4/5$ é menor que $1$, o limite existe. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000995641','40000000-0000-4000-8000-000000099564','Leia o objetivo','Separe o que o enunciado fornece da grandeza ou conclusão que ele pede.',1),('70000000-0000-4000-8000-000000995642','40000000-0000-4000-8000-000000099564','Reconheça a ideia','A descontinuidade está em $x=0$; como o expoente $4/5$ é menor que $1$, o limite existe.',2),('70000000-0000-4000-8000-000000995643','40000000-0000-4000-8000-000000099564','Escreva a relação','Registre a definição, fórmula ou teste que se aplica antes de simplificar.',3),('70000000-0000-4000-8000-000000995644','40000000-0000-4000-8000-000000099564','Desenvolva a análise','Execute a transformação necessária e obtenha: Converge e vale $5$.',4),('70000000-0000-4000-8000-000000995645','40000000-0000-4000-8000-000000099564','Confira a conclusão','Verifique sinais, domínio e hipóteses; só então compare o resultado com as quatro alternativas.',5) on conflict (id) do update set question_id=excluded.question_id,title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
