insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000995711','40000000-0000-4000-8000-000000099571','Nomeie primeiro a ideia central: Divida numerador e denominador por $n^2$, a maior potência do índice.',1),('60000000-0000-4000-8000-000000995712','40000000-0000-4000-8000-000000099571','Escreva a definição ou a relação escolhida antes de substituir os dados.',2),('60000000-0000-4000-8000-000000995713','40000000-0000-4000-8000-000000099571','Ao final, teste se o resultado preserva as condições do enunciado e descarte erros de sinal, domínio ou hipótese.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099571','$\frac{8}{6}$','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. Divida numerador e denominador por $n^2$, a maior potência do índice. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
