insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000099573','É decrescente, limitada inferiormente por $3$ e converge para $3$.','A habilidade avaliada é reconhecer a estrutura matemática antes de operar símbolos. A parcela $1/(n+3)$ diminui e permanece positiva quando $n$ cresce. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
